mapper.select:
SELECT l.lesson_id AS lessonId, l.lesson_title AS lessonTitle, l.lesson_num AS lessonNum, COALESCE(SUM(a.score), 0) AS studentScore, MAX(a.submit_time) AS submitTime FROM biz_lesson l INNER JOIN biz_student_answer a ON a.lesson_id = l.lesson_id WHERE a.student_id = #{studentId}
AND a.submit_time >= #{academicYearStart}
AND a.submit_time <= #{academicYearEnd}
GROUP BY l.lesson_id, l.lesson_title, l.lesson_num ORDER BY MAX(a.submit_time) ASC

SELECT 
    l.lesson_id AS lessonId,
    ROUND(AVG(student_total.total_score), 1) AS classAvgScore
FROM biz_lesson l
INNER JOIN (
    SELECT a.lesson_id, a.student_id, SUM(a.score) AS total_score
    FROM biz_student_answer a
    INNER JOIN biz_student s ON s.student_id = a.student_id
    INNER JOIN sys_user u ON s.user_id = u.user_id
    WHERE s.entry_year = #{entryYear}
      AND s.class_code = #{classCode}
      AND u.dept_id = #{deptId}

        AND a.submit_time >= #{academicYearStart}


        AND a.submit_time <= #{academicYearEnd}

    GROUP BY a.lesson_id, a.student_id
) student_total ON student_total.lesson_id = l.lesson_id
GROUP BY l.lesson_id

SELECT l.lesson_id AS lessonId, l.lesson_title AS lessonTitle, a.typing_speed AS typingSpeed, a.submit_time AS submitTime FROM biz_student_answer a INNER JOIN biz_lesson l ON l.lesson_id = a.lesson_id INNER JOIN biz_question q ON q.question_id = a.question_id WHERE a.student_id = #{studentId} AND q.question_type = 'typing' AND a.typing_speed IS NOT NULL
AND a.submit_time >= #{academicYearStart}
AND a.submit_time <= #{academicYearEnd}
ORDER BY a.submit_time ASC

SELECT p.lesson_id AS lessonId, l.lesson_title AS lessonTitle, p.score AS performance, p.create_time AS recordTime FROM biz_classroom_performance p INNER JOIN biz_lesson l ON l.lesson_id = p.lesson_id WHERE p.student_id = #{studentId} AND IFNULL(p.is_absent, 0) = 0 AND (p.score != 0 OR (p.score = 0 AND p.reason IS NOT NULL AND TRIM(p.reason) != ''))
AND p.create_time >= #{academicYearStart}
AND p.create_time <= #{academicYearEnd}
ORDER BY p.create_time ASC

SELECT 
    a.student_id AS studentId,
    a.lesson_id AS lessonId,
    SUM(a.score) AS totalScore,
    MAX(a.submit_time) AS submitTime
FROM biz_student_answer a
INNER JOIN biz_student s ON s.student_id = a.student_id
INNER JOIN sys_user u ON s.user_id = u.user_id
WHERE s.entry_year = #{entryYear}
  AND s.class_code = #{classCode}
  AND u.dept_id = #{deptId}

    AND a.submit_time >= #{academicYearStart}


    AND a.submit_time <= #{academicYearEnd}

GROUP BY a.student_id, a.lesson_id
ORDER BY a.lesson_id, SUM(a.score) DESC

SELECT COUNT(*)
FROM biz_student s
INNER JOIN sys_user u ON s.user_id = u.user_id
WHERE s.entry_year = #{entryYear}
  AND s.class_code = #{classCode}
  AND u.dept_id = #{deptId}
